import test from 'node:test';import assert from 'node:assert/strict';
import {Game,freshProfile} from '../src/game.js';import {Physics} from '../src/physics.js';import {reelState} from '../src/reels.js';
const ball=()=>({gold:false,large:false,hits:0,after:false});
test('one active spin plus five holds; overflow still pays the start award',()=>{const g=new Game(freshProfile(),0,()=>.5);for(let i=0;i<8;i++)g.hit(ball(),'start',4);assert.ok(g.spinActive);assert.equal(g.queue,5);assert.equal(g.total,16);g.tick(g.course.tempo+g.machine.reels.stopGap*2+.01);assert.equal(g.draws,1);assert.equal(g.queue,5);assert.ok(g.stopTimer>0);assert.equal(reelState(g).spinning,false);const stopped=[...g.stoppedReels];g.tick(.5);assert.deepEqual(reelState(g).numbers,stopped);assert.equal(g.queue,5);g.pause();g.tick(10);assert.ok(g.stopTimer>0);g.resume();g.tick(.4);g.tick(.01);assert.equal(g.queue,4);assert.ok(g.spinActive);});
test('misses stop on nonmatching varied digits instead of resetting to 371',()=>{const g=new Game(freshProfile(),0,()=>.5),seen=new Set();for(let i=0;i<10;i++){g.enqueueDraw();g.tick(g.course.tempo+g.machine.reels.stopGap*2+.01);const {numbers,spinning}=reelState(g);assert.equal(spinning,false);assert.notEqual(numbers.join(''),'371');assert.ok(!numbers.every(n=>n===numbers[0]));seen.add(numbers.join(''));g.tick(1);}assert.ok(seen.size>1);});
test('holds survive reach, jackpot, and stage choice, with no hidden overflow',()=>{const g=new Game(freshProfile(),0,()=>.5);g.beginPresentation(true);g.enqueueDraw(8);assert.equal(g.queue,5);g.award(g.target-g.stock);g.checkStage();g.tick(40);assert.equal(g.queue,5);g.selectSkill(g.choices[0].id);g.tick(30);assert.ok(g.jackpot);assert.equal(g.queue,5);assert.equal(g.enqueueDraw(),0);});
test('pocket approach balls drain without the age timeout across all three boards',()=>{for(let course=0;course<3;course++){const world=new Physics(course),g=new Game(freshProfile(),course,()=>.6);let maxAge=0,slowest=0;g.hit=b=>{maxAge=Math.max(maxAge,b.age);};g.lose=b=>{maxAge=Math.max(maxAge,b.age);};for(let x=40;x<=365;x+=5){world.balls.push({...ball(),id:world.nextId++,x,y:450,vx:0,vy:20,r:4.6,age:0});}for(let i=0;i<1200;i++){world.step(1/120,g);for(const b of world.balls)slowest=Math.max(slowest,b.age);}assert.equal(world.balls.length,0,`course ${course} stuck after 10 seconds`);assert.ok(maxAge<10,`course ${course} age ${maxAge}`);}});
test('reach stop digits persist after the reach ends',()=>{const g=new Game(freshProfile(),0,()=>.5);g.beginPresentation(false);const final=[...g.reelOutcome];g.tick(30);assert.deepEqual(g.stoppedReels,final);assert.equal(reelState(g).spinning,false);g.tick(.3);assert.deepEqual(reelState(g).numbers,final);});
